import type { z } from "zod";

export type HttpMethod = "get" | "post" | "put" | "patch" | "delete";

/** Typing-only route description; OpenAPI is generated by the API app from these. */
export interface RouteContract<
  Req extends z.ZodType = z.ZodType,
  Res extends z.ZodType = z.ZodType,
> {
  method: HttpMethod;
  path: string;
  summary?: string;
  request: Req;
  response: Res;
}

export function registerRoute<Req extends z.ZodType, Res extends z.ZodType>(
  route: RouteContract<Req, Res>,
): RouteContract<Req, Res> {
  return route;
}
